const fs = require('fs');

function generateCsvReport(url, o) {
  var p, u, g;
  const n = url.replace(/^https?:\/\//, "").replace(/\/.*/, "");
  const e = new Date().toISOString().split("T")[0];
  const s = [
    ["SEO/AEO/GEO Report", n, e],
    ["Generated by", "seoscore.tools", ""],
    [""],
    ["Category", "Score", "Passed", "Total"],
    ["Overall", Math.round(o.seo.score * .5 + o.aeo.score * .25 + o.geo.score * .25), "", ""],
    ["SEO", o.seo.score, o.seo.passed, o.seo.total],
    ["AEO", o.aeo.score, o.aeo.passed, o.aeo.total],
    ["GEO", o.geo.score, o.geo.passed, o.geo.total],
    ...((p = o.cwv) == null ? void 0 : p.score) != null ? [["CWV", o.cwv.score, o.cwv.passed, o.cwv.total]] : [],
    [""],
    ["Check ID", "Category", "Status", "Description"]
  ];

  function a(h, m) {
    m.forEach(f => {
      const w = f.applicable === false ? "N/A" : f.pass ? "PASS" : "FAIL";
      s.push([f.id, h, w, `"${f.label.replace(/"/g, '""')}"`]);
    });
  }

  a("SEO", o.seo.checks);
  a("AEO", o.aeo.checks);
  a("GEO", o.geo.checks);
  if ((g = (u = o.cwv) == null ? void 0 : u.checks) != null && g.length) {
    a("CWV", o.cwv.checks);
  }

  const i = s.map(h => h.join(",")).join("\n") + "\n";
  return "\uFEFF" + i;
}

if (process.argv.length < 4) {
  console.error("Usage: node web_csv.js <json_path> <url> [output_path]");
  process.exit(1);
}

const jsonPath = process.argv[2];
const pageUrl = process.argv[3];
const outputPath = process.argv[4];

const scanData = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
const csvContent = generateCsvReport(pageUrl, scanData);

if (outputPath) {
  fs.writeFileSync(outputPath, csvContent, 'utf8');
} else {
  process.stdout.write(csvContent);
}
